 output [AXI7_DATA_WIDTH-1:0]         axi7_rdata;
 output [1:0]                         axi7_rresp;
 output                               axi7_rlast;
 output                               axi7_rvalid;
 input                                axi7_rready;

 // AXI sideband signals
 input [AXI_AWUSERTAG_WIDTH-1:0]      axi7_awusertag; // sideband; user write tag; presented with bid
 output [AXI_AWUSERTAG_WIDTH-1:0]     axi7_busertag; // sideband; user write tag resposne

 // Port 7 interface
 input                                l_r_req_p7;
 input                                l_w_req_p7;
 input [2:0]                          l_req_pri_p7;
 input [BYTE_ADDR_WIDTH-1:0]          l_addr_p7;
 input [BURST_SIZE_WIDTH-1:0]         l_b_size_p7;
 input                                l_auto_pch_p7;
 input                                l_w_rmw_p7;  
 input [VPORT_ID_WIDTH-1:0]           l_vport_id_p7;
 input [TAG_WIDTH-1:0]                l_req_tag_p7;
 input                                l_rd_wrap_p7;
 output                               l_busy_p7;
 output                               l_r_valid_p7;
 output                               l_r_valid_last_p7;
 output                               l_d_req_p7;
 output                               l_d_req_last_p7;
 input [DSIZE-1:0]                    l_datain_p7;
 input [DSIZE/8-1:0]                  l_dm_in_p7;


 // tags corresponding to write and read data
 output [TAG_WIDTH-1:0]               l_d_req_tag; // Tag corresponding to l_d_req
 output [TAG_WIDTH-1:0]               l_r_valid_tag; // Tag corresponding to l_r_valid



 // Miscellaneous user controls
 input [NUMBER_OF_RANKS-1:0]          l_self_refresh;
 input [NUMBER_OF_RANKS-1:0]          l_power_down;     // SDRAM power down control; 1 = put devices into power down mode;
                                                        //                           0 = normal operation.
 input                                l_d_power_down;   // 1 = put ranks into deep power down when any l_power_down is asserted.
                                                        // 0 = normal power down operation

 input                                l_ref_req;        // Refresh Request
 output                               l_ref_ack;        // Refresh Acknowledge
 output [4:0]                         l_queue_level;    // Monitoring signals about how many command occupy internal queue
 output [SDRAM_BANKSTATMODULES-1:0]   l_activate_ready; // monitoring signal about activation status considering qm inside command
 input [NUMBER_OF_RANKS-1:0]          l_zq_cal_req; // Request ZQCL or ZQCS or ZQRESET(LPDDR2 only)(depends on setting of cfg_zq_cal_type)
 output                               l_zq_cal_ack; // Acknowledge of ZQCL or ZQCS or ZQRESET(LPDDR2 only)

 output wire [DSIZE-1:0]              l_dataout; // Local data out
 output wire [NUM_ECC*8-1:0]          l_ecc_check_dataout; // ECC check data associated with l_dataout

 output [1023:0]                       mpfe_status;

 // ECC related ports
 input [NUM_ECC-1:0]                  l_ecc_err_gen_1_bit; // generate a 1 bit ECC error on the associated l_datain cycle
 input [NUM_ECC-1:0]                  l_ecc_err_gen_2_bit; // generate a 2 bit ECC error on the associated l_datain cycle
 output [NUM_ECC-1:0]                 ecc_error_1bit;
 output [NUM_ECC-1:0]                 ecc_error_2bit;
 output [NUM_ECC*7-1:0]               ecc_error_pos;
 output                               ecc_rmw_error;
 output [BYTE_ADDR_WIDTH-1:0]         ecc_error_addr; // address of the errored read

